def icon(name, size=None, cls=""):
    s = f' width="{size}" height="{size}"' if size else ""
    return Markup(f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24"{s} class="{cls}" fill="none" stroke="currentColor" '
                  f'stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round">{P.get(name, "")}</svg>')
